+            m_b[i] = beta1 * m_b[i] + (1.0 - beta1) * g;
+            v_b[i] = beta2 * v_b[i] + (1.0 - beta2) * g * g;
+            let m_hat = m_b[i] / (1.0 - beta1.powf(t));
